import {
  CommonModule
} from '@angular/common';
import {
  Component,
  ChangeDetectionStrategy,
  HostListener,
  OnDestroy,
  ViewChild,
  computed,
  effect,
  inject,
  untracked
} from '@angular/core';
import {
  FormsModule
} from '@angular/forms';
import {
  MatButtonModule
} from '@angular/material/button';
import {
  MatIconModule
} from '@angular/material/icon';
import {
  APP_STATIC_DATA
} from '../../../shared/app-static-data';
import {
  AppUtils
} from '../../../shared/app-utils';
import {
  ExplanationGuideService,
  USER_PROFILE_SAVE_CONTEXT_KEY,
  UsersService
} from '../../../shared/core';
import {
  ProfileExtDto,
  UserDto
} from '../../../shared/core/contracts/user.interface';
import {
  HeaderCardComponent,
  ImageCarouselComponent,
  PopupComponent,
  type HeaderCardModel,
  type PopupControl,
  type PopupModel,
  ProfileExperienceManagerComponent
} from '../../../shared/ui';
import {
  AppMenuComponent,
  AppMenuDispatcher,
  AppMenuOutletComponent,
  type AppMenuItem,
  type AppMenuItemSelectEvent,
  type AppMenuModel,
  type AppMenuPalette
} from '../../../shared/ui/components/core/menu';
import {
  FormFlowComponent,
  type FormFlowActionEvent,
  type FormFlowDraft,
  type FormFlowModel
} from '../../../shared/ui/components/core/form/flow';
import {
  ProfileFormFlowDataConverter,
  ProfileFormFlowConverter,
  ProfileHeaderCardConverter,
  type ProfileFormFlowMenuContext
} from '../../../shared/ui/converters';
import {
  DialogStore
} from '../../../shared/ui/context/stores/dialog.store';
import {
  ProfileStore
} from '../../../shared/ui/context/stores/profile.store';
import type * as ProfileContracts from '../../../shared/core/contracts/profile.interface';

import type * as AppConstants from '../../../shared/core/common/constants';
import { UserProfileStore } from '../../../shared/ui/context/stores/user-profile.store';
import { AppRuntimeStore } from '../../../shared/ui/context/stores/app-runtime.store';
import { IntegrationSettingsPopupComponent } from '../integration-settings-popup/integration-settings-popup.component';
type ProfileEditorPanel = 'profile' | 'image' | 'experience';
type ProfileEditorMenuId = string;

type ProfileEditorMenuContext =
  | { kind: 'profileSave' }
  | { kind: 'profileStatus'; status: AppConstants.ProfileStatus };

@Component({
  selector: 'app-profile-editor',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    MatButtonModule,
    MatIconModule,
    AppMenuComponent,
    AppMenuOutletComponent,
    PopupComponent,
    FormFlowComponent,
    ImageCarouselComponent,
    HeaderCardComponent,
    ProfileExperienceManagerComponent,
    IntegrationSettingsPopupComponent
  ],
  providers: [
    AppMenuDispatcher
  ],
  templateUrl: './profile-editor.component.html',
  styleUrl: './profile-editor.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ProfileEditorComponent implements OnDestroy {
  @ViewChild(ProfileExperienceManagerComponent) private experienceManager?: ProfileExperienceManagerComponent;
  @ViewChild(IntegrationSettingsPopupComponent) private integrationSettingsPopup?: IntegrationSettingsPopupComponent;

  private readonly dialogStore = inject(DialogStore);
  private readonly userProfileStore = inject(UserProfileStore);
  private readonly runtimeStore = inject(AppRuntimeStore);
  private readonly menuDispatcher = inject(AppMenuDispatcher);
  private readonly profileStore = inject(ProfileStore);
  private readonly usersService = inject(UsersService);
  private readonly explanationGuide = inject(ExplanationGuideService);
  private readonly profileSaveLoadState = this.runtimeStore.selectLoadingState(USER_PROFILE_SAVE_CONTEXT_KEY);
  private lastLoadedUserId = '';
  private preparedProfile: ProfileExtDto | null = null;
  private draftChanged = false;
  private unregisterExplanationContext: (() => void) | null = null;
  private explanationContextActive = false;

  protected readonly isOpen = this.profileStore.profileEditorOpen;
  protected readonly activeUserIsAdmin = this.userProfileStore.activeUserIsAdmin;
  protected readonly activeUserIsOperator = this.userProfileStore.activeUserIsOperator;
  protected readonly activeUserUsesCompactProfile = computed(() =>
    this.activeUserIsAdmin() || this.activeUserIsOperator()
  );
  protected readonly isProfileSaving = computed(() => this.profileSaveLoadState().status === 'loading');
  protected readonly hasProfileSaveError = computed(() => {
    const status = this.profileSaveLoadState().status;
    return status === 'error' || status === 'timeout';
  });
  protected readonly showProfileSaveRing = computed(() => this.isProfileSaving() || this.hasProfileSaveError());
  protected readonly profileHeaderActionMenuModel: AppMenuModel = { actionSizing: 'content' };
  protected readonly profileApiIntegrationActions: readonly AppMenuItem[] = [{
    id: 'profile-api-integration',
    kind: 'action',
    icon: 'api',
    label: 'API',
    ariaLabel: 'Open API integration settings',
    layout: 'action',
    palette: 'blue'
  }];

  protected panel: ProfileEditorPanel = 'profile';
  protected profileEditorData = new ProfileExtDto();
  protected profileEditorFlowModel: FormFlowModel | null = null;
  protected profileCompletionPercent = 0;
  protected experienceFilter: ProfileContracts.ExperienceFilter = 'All';

  constructor() {
    effect(() => {
      const isOpen = this.profileStore.profileEditorOpen();
      this.setExplanationContext(isOpen);
      const activeProfileExt = this.userProfileStore.activeUserProfileExt();
      const activeUserId = this.userProfileStore.activeUserId().trim();

      if (!activeProfileExt || this.lastLoadedUserId && this.lastLoadedUserId !== activeUserId) {
        untracked(() => this.clearPreparedProfile());
      }

      if (!isOpen) {
        untracked(() => {
          this.resetTransientUiState();
          // Closing without saving still discards edits. An untouched form keeps
          // its DOM/model until authoritative data changes or the user leaves.
          if (this.draftChanged || this.preparedProfile !== activeProfileExt) {
            this.clearPreparedProfile();
          }
        });
        return;
      }

      if (!activeProfileExt || this.lastLoadedUserId === activeUserId) {
        return;
      }

      this.lastLoadedUserId = activeUserId;
      untracked(() => this.loadProfileEditorState(activeUserId, activeProfileExt));
    });
  }

  ngOnDestroy(): void {
    this.clearExplanationContext();
  }

  @HostListener('document:click', ['$event'])
  protected onDocumentClick(event: MouseEvent): void {
    if (!this.isOpen()) {
      return;
    }
    const target = event.target;
    if (!(target instanceof Element)) {
      return;
    }
  }

  @HostListener('window:keydown.escape', ['$event'])
  protected onWindowEscape(event: Event): void {
    if (!this.isOpen()) {
      return;
    }
    const keyboardEvent = event as KeyboardEvent;
    keyboardEvent.stopPropagation();
    void this.handleCloseAction();
  }

  protected get activeUser(): UserDto | null {
    return this.profileEditorData.profile.id && this.profileEditorData.profile.id === this.userProfileStore.activeUserId()
      ? this.profileEditorData.profile : null;
  }

  protected onProfileDraftChange(data: ProfileExtDto): void {
    this.profileEditorData = data;
    this.draftChanged = true;
  }

  private clearPreparedProfile(): void {
    this.lastLoadedUserId = '';
    this.preparedProfile = null;
    this.draftChanged = false;
    this.profileEditorData = new ProfileExtDto();
    this.profileEditorFlowModel = null;
  }

  private setExplanationContext(isOpen: boolean): void {
    if (this.explanationContextActive === isOpen) {
      return;
    }
    this.clearExplanationContext();
    if (isOpen) {
      this.explanationContextActive = true;
      this.unregisterExplanationContext = this.explanationGuide.registerContext('profile.editor');
    }
  }

  private clearExplanationContext(): void {
    this.unregisterExplanationContext?.();
    this.unregisterExplanationContext = null;
    this.explanationContextActive = false;
  }

  protected get profileEditorAge(): number {
    const profile = this.profileEditorData.profile;
    return AppUtils.ageFromIsoDate(profile.birthday, profile.age);
  }

  protected onProfileEditorFlowAction(event: FormFlowActionEvent): void {
    this.handleProfileFormFlowMenuContext(event.context as ProfileFormFlowMenuContext | undefined);
  }

  private handleProfileFormFlowMenuContext(context: ProfileFormFlowMenuContext | undefined): void {
    if (context?.menu === 'experienceSelector') {
      this.openExperienceSelector(context.value);
      return;
    }
    if (context?.menu === 'privacy') {
      this.setProfileDetailPrivacy(context.key, context.value);
      this.refreshProfileEditorFlowModel();
      return;
    }
  }

  protected popupTitle(): string {
    if (this.panel === 'image') {
      return 'Images';
    }
    if (this.activeUserIsAdmin()) {
      return 'Admin profile';
    }
    if (this.activeUserIsOperator()) {
      return 'Operator profile';
    }
    switch (this.panel) {
      case 'experience':
        return 'Experience';
      default:
        return 'Profile';
    }
  }

  protected profileEditorPopupModel(): PopupModel<ProfileEditorMenuContext> {
    const title = this.popupTitle();
    return {
      title,
      ariaLabel: title,
      closeAriaLabel: 'Close',
      size: 'wide',
      height: 'full',
      bodyLayout: 'fill',
      headerControls: this.profileEditorHeaderControls(),
      onClose: () => this.handleCloseAction(),
      onMenuSelect: event => this.onProfileEditorMenuSelect(event.itemSelect)
    };
  }

  protected profileEditorHeaderControls(): readonly PopupControl<ProfileEditorMenuContext>[] {
    if (this.panel !== 'profile') {
      return [];
    }
    const controls: PopupControl<ProfileEditorMenuContext>[] = [];
    if (!this.activeUserUsesCompactProfile()) {
      controls.push({
        id: 'profile-status',
        kind: 'menu',
        menuKind: 'select',
        trigger: this.profileStatusMenuTrigger(),
        items: this.profileStatusMenuItems(),
        panelAlign: 'end'
      });
    }
    controls.push({
      id: 'profile-actions',
      kind: 'menu',
      menuKind: 'inline',
      items: this.profileHeaderActionMenuItems(),
      panelAlign: 'end'
    });
    return controls;
  }

  protected onProfileApiIntegrationAction(event: AppMenuItemSelectEvent): void {
    if (event.id === 'profile-api-integration') {
      this.integrationSettingsPopup?.openPopup(event.sourceEvent);
    }
  }

  protected handleCloseAction(): void {
    if (this.panel !== 'profile') {
      this.panel = 'profile';
      return;
    }
    this.profileStore.closeProfileEditor();
    this.resetTransientUiState();
  }

  private async saveProfileFromHeader(event: Event): Promise<void> {
    event.stopPropagation();
    if (this.panel !== 'profile' || this.isProfileSaving()) {
      return;
    }
    await this.commitProfileForm(false);
    this.profileStore.closeProfileEditor();
    this.resetTransientUiState();
  }

  protected onBackdropClose(): void {
    void this.handleCloseAction();
  }

  protected openImageEditor(): void {
    this.panel = 'image';
  }

  protected openExperienceSelector(filter: ProfileContracts.ExperienceFilter = 'All'): void {
    this.experienceFilter = filter;
    this.experienceManager?.setFilter(filter);
    this.panel = 'experience';
  }

  protected onProfileImagesChange(imageUrls: readonly string[]): void {
    this.profileEditorData = {
      ...this.profileEditorData,
      profile: {
        ...this.profileEditorData.profile,
        images: [...imageUrls]
      }
    };
    this.refreshProfileEditorFlowModel();
  }

  protected profileStatusMenuTrigger() {
    const status = this.profileEditorData.profile.profileStatus ?? 'public';
    return {
      label: status,
      icon: this.profileStatusIcon(status),
      palette: this.profileStatusPalette(status),
      layout: 'pill' as const,
      ariaLabel: 'Open profile status selector'
    };
  }

  private profileStatusMenuItems(): readonly AppMenuItem<ProfileEditorMenuId, ProfileEditorMenuContext>[] {
    const currentStatus = this.profileEditorData.profile.profileStatus ?? 'public';
    return APP_STATIC_DATA.profileStatusOptions.map(option => ({
      id: `profile-status-${option.value}`,
      label: option.value,
      icon: option.icon,
      kind: 'radio',
      value: option.value,
      active: option.value === currentStatus,
      checked: option.value === currentStatus,
      palette: this.profileStatusPalette(option.value),
      surface: 'tinted',
      context: { kind: 'profileStatus', status: option.value }
    }));
  }

  protected profileHeaderActionMenuItems(): readonly AppMenuItem<ProfileEditorMenuId, ProfileEditorMenuContext>[] {
    return [{
      id: 'profile-save',
      icon: 'done',
      kind: 'action',
      palette: 'green',
      disabled: () => this.isProfileSaving(),
      progress: {
        state: () => this.showProfileSaveRing()
          ? this.hasProfileSaveError() ? 'error' : 'loading'
          : null,
        shape: 'circle'
      },
      ariaLabel: 'Save profile',
      context: { kind: 'profileSave' }
    }];
  }

  protected onProfileEditorMenuSelect(
    event: AppMenuItemSelectEvent<ProfileEditorMenuId, ProfileEditorMenuContext>
  ): void {
    const context = event.context;
    if (!context) {
      return;
    }

    if (context.kind === 'profileSave') {
      void this.saveProfileFromHeader(event.sourceEvent);
      return;
    }
    if (context.kind === 'profileStatus') {
      this.profileEditorData = {
        ...this.profileEditorData,
        profile: {
          ...this.profileEditorData.profile,
          profileStatus: context.status
        }
      };
      this.refreshProfileEditorFlowModel();
    }
  }

  protected onProfileEditorDispatchedMenuSelect(
    event: AppMenuItemSelectEvent<ProfileEditorMenuId, unknown>
  ): void {
    const context = event.context as ProfileEditorMenuContext | ProfileFormFlowMenuContext | undefined;
    if ((context as ProfileEditorMenuContext | undefined)?.kind === 'profileSave') {
      this.onProfileEditorMenuSelect(event as AppMenuItemSelectEvent<ProfileEditorMenuId, ProfileEditorMenuContext>);
      return;
    }
    this.handleProfileFormFlowMenuContext(context as ProfileFormFlowMenuContext | undefined);
  }

  private profileStatusIcon(status: AppConstants.ProfileStatus): string {
    return APP_STATIC_DATA.profileStatusOptions.find(option => option.value === status)?.icon
      ?? (status === 'blocked' ? 'block' : status === 'deleted' ? 'delete' : 'public');
  }

  private profileStatusPalette(status: AppConstants.ProfileStatus): AppMenuPalette {
    switch (status) {
      case 'public':
        return 'green';
      case 'friends only':
        return 'blue';
      case 'host only':
        return 'brown';
      case 'inactive':
        return 'muted';
      case 'blocked':
      case 'deleted':
        return 'red';
      default:
        return 'neutral';
    }
  }

  protected onExperienceEntriesChange(entries: readonly ProfileContracts.ExperienceEntry[]): void {
    this.setExperienceEntries(entries);
  }

  protected onProfileCompletionPercentChange(percent: number): void {
    this.profileCompletionPercent = Math.max(0, Math.min(100, Math.trunc(Number(percent) || 0)));
  }

  protected profileHeaderCardModel(): HeaderCardModel {
    const admin = this.activeUserIsAdmin();
    const operator = this.activeUserIsOperator();
    const profile = this.profileEditorData.profile;
    const model = ProfileHeaderCardConverter.convert(profile, {
      admin: admin || operator,
      age: this.profileEditorAge,
      completionPercent: this.profileCompletionPercent,
      showEdit: true,
      editAriaLabel: 'Open image editor'
    });
    return operator
      ? {
          ...model,
          badgeLabel: 'OPERATOR',
          meta: profile.headline.trim() || 'Operator workspace',
          metaIcon: 'settings_input_component'
        }
      : model;
  }

  private loadProfileEditorState(userId: string, activeProfileExt: ProfileExtDto | null): void {
    this.resetTransientUiState();
    const normalizedUserId = userId.trim();
    if (!this.isOpen() || this.lastLoadedUserId !== normalizedUserId) {
      return;
    }
    if (!activeProfileExt) {
      return;
    }
    this.profileCompletionPercent = Math.max(0, Math.min(100, Math.trunc(Number(activeProfileExt.profile.completion) || 0)));
    this.profileEditorData = ProfileFormFlowDataConverter.convert(
      this.profileEditorDraft(activeProfileExt)
    ).data;
    this.refreshProfileEditorFlowModel();
    this.preparedProfile = activeProfileExt;
    this.draftChanged = false;
    this.panel = 'profile';
  }

  private profileEditorDraft(data: ProfileExtDto): FormFlowDraft<ProfileExtDto> {
    return {
      version: 1,
      userId: data.profile.id.trim(),
      currentStepId: 'basics',
      updatedAtIso: new Date().toISOString(),
      completedStepIds: [],
      skippedStepIds: [],
      data
    };
  }

  private profileEditorPrivacyValues(): Record<string, AppConstants.DetailPrivacy> {
    const values: Record<string, AppConstants.DetailPrivacy> = {};
    for (const group of this.profileEditorData.profile.profileDetails ?? []) {
      for (const row of group.rows) {
        values[row.labelKey] = row.privacy;
      }
    }
    return values;
  }

  private refreshProfileEditorFlowModel(): void {
    this.draftChanged = true;
    this.profileEditorFlowModel = ProfileFormFlowConverter.convert(
      this.profileEditorDraft(this.profileEditorData),
      {
        title: 'Profile',
        subtitle: '',
        userId: this.profileEditorData.profile.id,
        layout: 'grouped',
        profileSize: this.activeUserUsesCompactProfile() ? 'small' : 'big',
        imageEditor: 'external',
        privacy: {
          values: this.profileEditorPrivacyValues()
        },
        showHeader: false,
        showSave: false
      }
    );
  }

  private profileDetailRowByKey(labelKey: string): ProfileContracts.ProfileDetailFormRow | null {
    const target = AppUtils.normalizeText(labelKey);
    for (const group of this.profileEditorData.profile.profileDetails ?? []) {
      for (const row of group.rows) {
        if (AppUtils.normalizeText(row.labelKey) === target) {
          return row;
        }
      }
    }
    return null;
  }

  private setProfileDetailPrivacy(labelKey: string, value: AppConstants.DetailPrivacy): void {
    const row = this.profileDetailRowByKey(labelKey);
    if (!row) {
      return;
    }
    row.privacy = value;
    this.profileEditorData = {
      ...this.profileEditorData,
      profile: {
        ...this.profileEditorData.profile,
        profileDetails: [...(this.profileEditorData.profile.profileDetails ?? [])]
      }
    };
    this.refreshProfileEditorFlowModel();
  }

  private setExperienceEntries(entries: readonly ProfileContracts.ExperienceEntry[]): void {
    const nextEntries = [...entries];
    this.profileEditorData = {
      ...this.profileEditorData,
      experienceEntries: nextEntries
    };
    this.refreshProfileEditorFlowModel();
  }

  private async commitProfileForm(showAlert: boolean): Promise<void> {
    if (!this.profileEditorData.profile.id) {
      return;
    }
    const saved = await this.usersService.saveUserProfileExt(this.profileEditorData);
    if (saved && saved.id === this.userProfileStore.activeUserId()) {
      this.loadProfileEditorState(saved.id, this.userProfileStore.activeUserProfileExt());
    }
    if (showAlert) {
      this.dialogStore.openInfo('Profile saved', {
        title: 'Profile updated',
        confirmTone: 'neutral'
      });
    }
  }

  private resetTransientUiState(): void {
    this.menuDispatcher.close();
    this.panel = 'profile';
  }
}
